#include <iostream>
#include <memory>
#include <string>

struct Player
{
    std::string name;
    int x;
    Player(std::string name, int x) : name(name), x(x) {}
    ~Player() { std::cout << "  (" << name << " left the game)\n"; }
};

int main()
{
    auto player = std::make_shared<Player>("Amina", 10);
    auto camera = player;                      // a second owner
    std::cout << "owners: " << player.use_count() << "\n";

    std::weak_ptr<Player> enemyTarget = player; // watching, not owning
    std::cout << "owners still: " << player.use_count() << "\n";

    camera.reset();
    player.reset();                             // last owner gone: Player deleted

    if (auto p = enemyTarget.lock())
        std::cout << "chasing " << p->name << "\n";
    else
        std::cout << "target gone, enemy wanders\n";
    return 0;
}

