#include <map>
#include <memory>
#include <string>

struct Texture
{
    inline static int alive = 0;
    std::string file;
    Texture(std::string file) : file(file) { alive++; }
    ~Texture() { alive--; }
};

class TextureCache
{
public:
    std::shared_ptr<Texture> load(const std::string& file)
    {
        auto it = textures.find(file);
        if (it != textures.end()) return it->second;   // share the one we have
        auto t = std::make_shared<Texture>(file);
        textures[file] = t;
        return t;
    }
    int loadedCount() const { return textures.size(); }
    void unloadUnused()
    {
        for (auto it = textures.begin(); it != textures.end(); ) {
            if (it->second.use_count() == 1) it = textures.erase(it);   // only we hold it
            else ++it;
        }
    }
private:
    std::map<std::string, std::shared_ptr<Texture>> textures;
};

