#include <memory>
#include <string>

struct Player
{
    std::string name;
    int x;
    Player(std::string name, int x) : name(name), x(x) {}
};

class Follower
{
public:
    void follow(const std::shared_ptr<Player>& p) { target = p; }
    bool hasTarget() const { return !target.expired(); }
    std::string targetName() const
    {
        if (auto p = target.lock()) return p->name;
        return "none";
    }
    int stepToward(int myX) const
    {
        auto p = target.lock();       // a short-lived owner while we read it
        if (!p) return myX;
        if (p->x > myX) return myX + 1;
        if (p->x < myX) return myX - 1;
        return myX;
    }
private:
    std::weak_ptr<Player> target;     // watches, never keeps the player alive
};

