#include <string>
#include <vector>

struct Soldier;

struct Squad
{
    inline static int alive = 0;
    std::string name;
    std::vector<std::shared_ptr<Soldier>> members;   // the squad owns its soldiers
    Squad(std::string name) : name(name) { alive++; }
    ~Squad() { alive--; }
};

struct Soldier
{
    inline static int alive = 0;
    std::string name;
    std::shared_ptr<Squad> squad;     // PROBLEM: a soldier also owns its squad
    Soldier(std::string name) : name(name) { alive++; }
    ~Soldier() { alive--; }
};

std::shared_ptr<Soldier> enlist(const std::shared_ptr<Squad>& squad, const std::string& name)
{
    auto s = std::make_shared<Soldier>(name);
    s->squad = squad;
    squad->members.push_back(s);
    return s;
}

std::string squadOf(const Soldier& s)
{
    return s.squad ? s.squad->name : "none";
}

